/**
 * Which of Nova's lines have a recorded clip in public/audio/nova — one
 * character per line, in list order, '1' where the clip exists. Generated by
 * scripts/nova-voice.mjs after the clips are cut; do not edit by hand. A line
 * without a clip is shown as text only.
 */
export const CLIPS: Partial<Record<string, string>> = {
  greet: '11111111111111111111',
  greet_easy: '111111',
  greet_normal: '111111',
  greet_hard: '111111',
  greet_insane: '111111',
  rematch_won: '11111111',
  rematch_lost: '11111111',
  opening: '11111111',
  opening_corner: '111111',
  player_chain: '11111111111111111111111111',
  player_huge: '111111111111111',
  risky: '111111111111',
  cpu_think: '11111111111111',
  cpu_chain: '11111111111111111111111111',
  cpu_huge: '111111111111',
  player_leading: '1111111111111111111111',
  cpu_leading: '11111111111111111111',
  comeback: '1111111111',
  cpu_comeback: '11111111',
  close: '1111111111',
  near_out_cpu: '111111111111',
  near_out_player: '111111111111',
  ambient: '111111111111111111111111111111',
  idle: '11111111111111',
  tip: '11111111',
  player_win: '11111111111111111111111111',
  cpu_win: '11111111111111111111111111',
  welcome: '1',
  tut: '111111111111111111',
};

export function hasClip(category: string, index: number): boolean {
  return CLIPS[category]?.[index] === '1';
}
